 "content": "def transform(grid):
    # The smaller colored motif is the repetition tile for the adjacent 0-valued panel.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = 8
    # locate axis-aligned rectangular zero panels, excluding single motif cells
    panels=[]
    seen=set()
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                        if 0<=nx<h and 0<=ny<w and g[nx][ny]==0 and (nx,ny) not in seen:
                            seen.add((nx,ny)); stack.append((nx,ny))
                rs=[x for x,y in cells]; cs=[y for x,y in cells]
                if len(cells)>4 and len(cells)==(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1):
                    panels.append((min(rs),min(cs),max(rs),max(cs)))
    # choose the compact nonzero motif's color and bounding rectangle; repeat its pattern
    # across the nearest large zero panel, preserving zeros in the motif as holes.
    colors={v for row in g for v in row if v not in (0,bg)}
    for color in colors:
        pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==color]
        if not pts: continue
        r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
        tile=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        targets=[p for p in panels if p[2]-p[0]+1>r1-r0+1 or p[3]-p[1]+1>c1-c0+1]
        if not targets: continue
        # Closest panel by Manhattan distance between boxes
        tr,tc,br,bc=min(targets,key=lambda p: abs((p[0]+p[2]-r0-r1)//2)+abs((p[1]+p[3]-c0-c1)//2))
        for r in range(tr,br+1):
            for c in range(tc,bc+1):
                v=tile[(r-tr)%(r1-r0+1)][(c-tc)%(c1-c0+1)]
                if v != 0: g[r][c]=v
    return g
"
