 "content": "def transform(grid):
    g=[r[:] for r in grid]; h=len(g); w=len(g[0])
    colors={v for row in g for v in row if v not in (0,8)}
    # Fill each solid rectangular zero canvas by repeating the motif of its own color.
    for color in colors:
        pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==color]
        r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
        tile=[[g[r][c] if g[r][c]==color else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        # zero rectangles have foreground zeros, so find all-zero bounding rectangles by scanning rows/columns
        # and select the rectangular block closest to the motif, with area larger than its bbox.
        cand=[]
        for a in range(h):
          for b in range(w):
            for hh in range(len(tile),h-a+1):
              for ww in range(len(tile[0]),w-b+1):
                if hh*ww<=len(pts)*2: continue
                if all(g[x][y]==0 for x in range(a,a+hh) for y in range(b,b+ww)):
                  cand.append((a,b,a+hh-1,b+ww-1))
        if not cand: continue
        # Largest all-zero rectangle is the intended canvas.
        tr,tc,br,bc=max(cand,key=lambda p:(p[2]-p[0]+1)*(p[3]-p[1]+1))
        for r in range(tr,br+1):
          for c in range(tc,bc+1): g[r][c]=tile[(r-tr)%len(tile)][(c-tc)%len(tile[0])]
    return g
